package cn.mop.adapters.scp;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import org.junit.jupiter.api.*;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.security.*;
import java.security.interfaces.RSAPublicKey;
import java.time.*;
import java.util.*;
import javax.crypto.Cipher;
import static org.junit.jupiter.api.Assertions.*;

/** Synthetic inputs only. No SCP credentials, TLS service, database or network are used. */
class ScpConnectorTest {
    static final Instant NOW=Instant.parse("2026-10-12T08:00:00Z");
    static final String TENANT="55000000-0000-4000-8000-000000000001",ASSET="55000000-0000-4000-8000-000000000002";
    static final ScpProtocol.Scope SCOPE=new ScpProtocol.Scope("pool-synthetic","project-synthetic");
    static KeyPair keys;static String modulus;
    @BeforeAll static void keys()throws Exception{KeyPairGenerator generator=KeyPairGenerator.getInstance("RSA");generator.initialize(2048);keys=generator.generateKeyPair();modulus=((RSAPublicKey)keys.getPublic()).getModulus().toString(16);}
    static byte[] bytes(String value){return value.getBytes(StandardCharsets.UTF_8);}
    static JsonNode json(Object value){return ScpProtocol.JSON.valueToTree(value);}
    static byte[] encoded(Object value){try{return ScpProtocol.JSON.writeValueAsBytes(value);}catch(Exception error){throw new AssertionError(error);}}
    static ObjectNode config(){return (ObjectNode)json(new LinkedHashMap<>(Map.ofEntries(
        Map.entry("schema_version",1),Map.entry("enabled",true),Map.entry("base_url","https://192.168.1.179"),
        Map.entry("tenant_id",TENANT),Map.entry("asset_id",ASSET),Map.entry("resource_pool_id",SCOPE.poolId()),Map.entry("scp_project_id",SCOPE.projectId()),
        Map.entry("auth_mode","PASSWORD"),Map.entry("username_ref","MOP_SCP_USERNAME"),Map.entry("password_ref","MOP_SCP_PASSWORD"),
        Map.entry("access_key_ref","MOP_SCP_ACCESS_KEY"),Map.entry("secret_key_ref","MOP_SCP_SECRET_KEY"),Map.entry("region","test-region"),Map.entry("service","test-api"),
        Map.entry("legacy_cookie_required",false),Map.entry("public_key_api","V2"),Map.entry("tls_mode","SYSTEM"),Map.entry("ca_file_ref","MOP_SCP_CA_FILE"))));}
    static ScpSettings settings(ObjectNode config){return ScpSettings.parse(encoded(config));}
    static Map<String,String> secrets(){return Map.of("MOP_SCP_USERNAME","SYNTHETIC_READER","MOP_SCP_PASSWORD","SYNTHETIC_PASSWORD_ONLY","MOP_SCP_ACCESS_KEY","SYNTHETIC_ACCESS","MOP_SCP_SECRET_KEY","SYNTHETIC_ONLY_SECRET");}
    static void reason(String expected,org.junit.jupiter.api.function.Executable task){assertEquals(expected,assertThrows(ScpProtocol.Failure.class,task).reason);}
    static Map<String,Object> row(){return new LinkedHashMap<>(Map.of("id","synthetic-host","az_id",SCOPE.poolId(),"project_id",SCOPE.projectId(),"status","future_state","name","Synthetic host","cpu",Map.of("ratio",new BigDecimal("0.45"),"used_mhz",new BigDecimal("1234.567890123456789")))) ;}
    static JsonNode page(List<?> rows,String next){return json(Map.of("page_num",0,"page_size",100,"total_size",rows.size(),"next_page_num",next,"data",rows));}
    static JsonNode tokenData(Instant issued,Instant expires){return json(Map.of("access",Map.of("token",Map.of("id","SYNTHETIC_TOKEN_ONLY","issued_at",issued.toString(),"expires",expires.toString()))));}
    @Test void exampleStaysDisabledAndUnverified()throws Exception{Path root=Path.of("").toAbsolutePath();while(!Files.exists(root.resolve("deploy/scp/connection.example.json")))root=root.getParent();var s=ScpSettings.parse(Files.readAllBytes(root.resolve("deploy/scp/connection.example.json")));assertFalse(s.enabled);assertFalse(s.runtimeReadyVerified());assertTrue(s.problems(k->null).containsAll(List.of("DISABLED","AUTH_MODE_PENDING","MOP_AND_SCP_SCOPE_PENDING","CA_FILE_PENDING")));reason("CONFIG_PENDING",()->ScpClient.configured(s,k->null));}
    @Test void configurationRejectsInlineSecretsUnknownKeysAndDuplicateJson(){var c=config();c.put("password","SYNTHETIC");reason("INVALID_CONFIGURATION",()->settings(c));String duplicate=new String(encoded(config()),StandardCharsets.UTF_8).replace("\"enabled\":true","\"enabled\":true,\"enabled\":true");reason("INVALID_CONFIGURATION",()->ScpSettings.parse(bytes(duplicate)));}
    @Test void validConfigurationDoesNotVerifyRuntimeOrReadSecretsTwice(){var s=settings(config());Map<String,Integer> calls=new HashMap<>();assertEquals(List.of(),s.problems(k->{calls.merge(k,1,Integer::sum);return secrets().get(k);}));assertTrue(calls.values().stream().allMatch(n->n==1));assertFalse(s.runtimeReadyVerified());}
    @Test void failedSecretResolverBecomesPendingWithoutExceptionContent(){var s=settings(config());assertTrue(s.problems(k->{throw new IllegalStateException("DO_NOT_ECHO");}).contains("READ_ONLY_CREDENTIALS_PENDING"));}
    @Test void invalidMopScopePrivateReferenceAndCookiePolicyFail(){var badScope=config();badScope.put("tenant_id","other");reason("INVALID_MOP_SCOPE",()->settings(badScope));var badRef=config();badRef.put("password_ref","actual-password");reason("INVALID_PRIVATE_REFERENCE",()->settings(badRef));var badCookie=config();badCookie.put("legacy_cookie_required","false");reason("INVALID_COOKIE_POLICY",()->settings(badCookie));}
    @Test void ec2NeedsExplicitSigningScope(){var c=config();c.put("auth_mode","EC2");c.putNull("service");assertTrue(settings(c).problems(secrets()::get).contains("EC2_SIGNING_SCOPE_PENDING"));}
    @Test void explicitHttpsOriginHasNoCredentialsQueryOrExtraPath(){assertEquals("https://192.168.1.179",ScpProtocol.origin("https://192.168.1.179/").toString());for(String uri:List.of("http://192.168.1.179","https://u:p@192.168.1.179","https://192.168.1.179/path","https://192.168.1.179?q=1","https://192.168.1.179#x"))reason("INVALID_HTTPS_ORIGIN",()->ScpProtocol.origin(uri));}
    @Test void privateScopeIsEncodedIntoOnlyFixedReadPaths(){var r=ScpProtocol.page(ScpProtocol.Kind.SERVER,SCOPE,0,100);assertEquals("GET",r.method());assertEquals("/janus/20180725/servers?az_id=pool-synthetic&page_num=0&page_size=100&project_id=project-synthetic",r.target());assertEquals(0,r.body().length);assertEquals("/janus/20180725/azs/pool-synthetic",ScpProtocol.pool(SCOPE).path());}
    @Test void invalidScopeCannotInjectQueriesOrPaths(){for(String id:List.of("../pool","p/1","p?project_id=other","p%2fother","p\nheader"))reason("INVALID_SOURCE_IDENTIFIER",()->new ScpProtocol.Scope(id,"p"));}
    @Test void pageBudgetAndNegativePageAreRejected(){reason("INVALID_PAGE_REQUEST",()->ScpProtocol.page(ScpProtocol.Kind.HOST,SCOPE,-1,100));reason("INVALID_PAGE_REQUEST",()->ScpProtocol.page(ScpProtocol.Kind.HOST,SCOPE,0,101));reason("INVALID_PAGE_REQUEST",()->ScpProtocol.page(ScpProtocol.Kind.HOST,SCOPE,0,0));}
    @Test void sourceMessagesDoNotEscapeHttpAndApplicationFailures(){for(int code:List.of(401,403,429,500,302)){var error=assertThrows(ScpProtocol.Failure.class,()->ScpProtocol.envelope(code,"application/json",bytes("SECRET_SOURCE")));assertFalse(error.toString().contains("SECRET_SOURCE"));}reason("PROVIDER_ERROR",()->ScpProtocol.envelope(200,"application/json",bytes("{\"message\":\"SECRET_SOURCE\",\"code\":1,\"data\":{}}")));}
    @Test void hugeProviderErrorCannotOverflowToSuccess(){reason("PROVIDER_ERROR",()->ScpProtocol.envelope(200,"application/json",bytes("{\"message\":\"\",\"code\":18446744073709551616,\"data\":{}}")));}
    @Test void envelopeRequiresExplicitLegacySuccessNotNewerErrcode(){assertTrue(ScpProtocol.envelope(200,"application/json; charset=utf-8",encoded(Map.of("message","","code",0,"data",Map.of()))).isObject());for(String error:List.of("{\"message\":\"\",\"errcode\":\"\",\"data\":{}}","{\"message\":\"\",\"code\":\"0\",\"data\":{}}","{\"code\":0,\"data\":{}}"))reason("UNSUPPORTED_ENVELOPE",()->ScpProtocol.envelope(200,"application/json",bytes(error)));}
    @Test void parserRejectsDuplicateKeysTrailingJsonInvalidUtf8AndHtml(){for(String text:List.of("{\"message\":\"\",\"code\":0,\"code\":1,\"data\":{}}","{\"message\":\"\",\"code\":0,\"data\":{}} {}"))reason("INVALID_JSON",()->ScpProtocol.envelope(200,"application/json",bytes(text)));reason("INVALID_JSON",()->ScpProtocol.envelope(200,"application/json",new byte[]{(byte)0xff}));reason("INVALID_RESPONSE_FORMAT",()->ScpProtocol.envelope(200,"text/html",bytes("<html>login</html>")));reason("INVALID_RESPONSE_FORMAT",()->ScpProtocol.envelope(200,"application/json",new byte[ScpProtocol.MAX_BODY+1]));}
    @Test void sourceEnvelopeCannotBeMistakenForBareArray(){reason("UNSUPPORTED_ENVELOPE",()->ScpProtocol.envelope(200,"application/json",bytes("[]")));}
    @Test void pagesPreserveRawRatiosPrecisionUnknownStateAndMissingValues(){var result=ScpProtocol.decodePage(page(List.of(row()),""),ScpProtocol.Kind.HOST,SCOPE,0,100,NOW);var item=result.items().get(0);assertEquals("0.45",item.quantities().get("cpu.ratio"));assertEquals("1234.567890123456789",item.quantities().get("cpu.used_mhz"));assertFalse(item.quantities().containsKey("memory.ratio"));assertEquals("future_state",item.sourceStatus());assertNull(item.sampledAt());assertEquals(NOW,item.receivedAt());assertFalse(result.completeInventoryVerified());}
    @Test void unexpectedSourceFieldsAreNotProjected(){var row=row();row.put("password","SOURCE_SECRET");row.put("keypair",Map.of("private_key","SOURCE_PRIVATE_KEY"));var result=ScpProtocol.decodePage(page(List.of(row),""),ScpProtocol.Kind.HOST,SCOPE,0,100,NOW).items().get(0);assertFalse(result.attributes().containsKey("password"));assertFalse(result.attributes().containsKey("keypair"));assertFalse(result.toString().contains("SOURCE_"));}
    @Test void emptyPageIsExplicitButNotCertifiedCompleteInventory(){var result=ScpProtocol.decodePage(page(List.of(),""),ScpProtocol.Kind.HOST,SCOPE,0,100,NOW);assertTrue(result.items().isEmpty());assertNull(result.nextPage());assertFalse(result.completeInventoryVerified());}
    @Test void crossPoolAndServerProjectMismatchFailClosed(){var r=row();r.put("az_id","other");reason("SOURCE_SCOPE_MISMATCH",()->ScpProtocol.decodePage(page(List.of(r),""),ScpProtocol.Kind.HOST,SCOPE,0,100,NOW));r.put("az_id",SCOPE.poolId());r.put("project_id","other");reason("SOURCE_SCOPE_MISMATCH",()->ScpProtocol.decodePage(page(List.of(r),""),ScpProtocol.Kind.SERVER,SCOPE,0,100,NOW));r.remove("project_id");reason("SOURCE_SCOPE_MISMATCH",()->ScpProtocol.decodePage(page(List.of(r),""),ScpProtocol.Kind.SERVER,SCOPE,0,100,NOW));}
    @Test void duplicateObjectsAndWrongPageMetadataFailClosed(){reason("SOURCE_SCOPE_MISMATCH",()->ScpProtocol.decodePage(page(List.of(row(),row()),""),ScpProtocol.Kind.HOST,SCOPE,0,100,NOW));reason("PAGINATION_MISMATCH",()->ScpProtocol.decodePage(page(List.of(row()),""),ScpProtocol.Kind.HOST,SCOPE,1,100,NOW));}
    @Test void nextPageMustAdvanceAndCannotBeUrl(){for(String next:List.of("0","-1","10001","https://x","01"))reason("INVALID_NEXT_PAGE",()->ScpProtocol.decodePage(page(List.of(row()),next),ScpProtocol.Kind.HOST,SCOPE,0,100,NOW));reason("INVALID_SOURCE_FIELD",()->ScpProtocol.decodePage(page(List.of(row()),"https://long-host"),ScpProtocol.Kind.HOST,SCOPE,0,100,NOW));assertEquals(2,ScpProtocol.decodePage(page(List.of(row()),"2"),ScpProtocol.Kind.HOST,SCOPE,0,100,NOW).nextPage());}
    @Test void emptyPageWithNextPointerIsNotInventedSuccess(){reason("INVALID_NEXT_PAGE",()->ScpProtocol.decodePage(page(List.of(),"1"),ScpProtocol.Kind.HOST,SCOPE,0,100,NOW));}
    @Test void invalidQuantityTypesAndSignsAreRejected(){for(Object value:List.of("12",-1)){var r=row();r.put("cpu",Map.of("ratio",value));reason("INVALID_QUANTITY",()->ScpProtocol.decodePage(page(List.of(r),""),ScpProtocol.Kind.HOST,SCOPE,0,100,NOW));}}
    @Test void serverUsesDocumentedStatusQuantityObjects(){var r=row();r.remove("cpu");r.put("cpu_status",Map.of("used_mhz",100));r.put("memory_status",Map.of("used_mb",512));var result=ScpProtocol.decodePage(page(List.of(r),""),ScpProtocol.Kind.SERVER,SCOPE,0,100,NOW).items().get(0);assertEquals("100",result.quantities().get("cpu.used_mhz"));assertEquals("512",result.quantities().get("memory.used_mb"));}
    @Test void poolLookupMustMatchExplicitId(){reason("SOURCE_SCOPE_MISMATCH",()->ScpProtocol.decodePool(json(Map.of("id","other")),SCOPE));assertEquals(SCOPE.poolId(),ScpProtocol.decodePool(json(Map.of("id",SCOPE.poolId(),"status","new_state")),SCOPE).get("id"));}
    @Test void rsaPasswordEncryptionMatchesDocumentedPkcs1AndHex()throws Exception{char[] password="Synthetic-中文-123".toCharArray();String cipherText=ScpAuthentication.encryptPassword(password,modulus.toUpperCase()+"\n");Cipher cipher=Cipher.getInstance("RSA/ECB/PKCS1Padding");cipher.init(Cipher.DECRYPT_MODE,keys.getPrivate());assertEquals(new String(password),new String(cipher.doFinal(HexFormat.of().parseHex(cipherText)),StandardCharsets.UTF_8));assertNotEquals(cipherText,ScpAuthentication.encryptPassword(password,modulus));}
    @Test void malformedModulusAndOversizePasswordFailBeforeRequest(){for(String key:List.of("not-hex","0".repeat(512),modulus+"\n\n",modulus+" "))assertThrows(ScpProtocol.Failure.class,()->ScpAuthentication.encryptPassword("test".toCharArray(),key));reason("PASSWORD_TOO_LONG_FOR_KEY",()->ScpAuthentication.encryptPassword("x".repeat(300).toCharArray(),modulus));assertThrows(ScpProtocol.Failure.class,()->ScpAuthentication.encryptPassword(new char[]{'\ud800'},modulus));}
    @Test void tokenUsesActualExpiryAndRedactsValue(){var token=ScpAuthentication.token(tokenData(NOW.minusSeconds(5),NOW.plusSeconds(120)),NOW);assertEquals("Token SYNTHETIC_TOKEN_ONLY",token.authorization(NOW));assertFalse(token.toString().contains("SYNTHETIC"));reason("TOKEN_EXPIRED_OR_CLOCK_SKEW",()->token.authorization(NOW.plusSeconds(91)));}
    @Test void tokenRejectsClockSkewPastExpiryAndHeaderInjection(){reason("TOKEN_EXPIRED_OR_CLOCK_SKEW",()->ScpAuthentication.token(tokenData(NOW.plusSeconds(1),NOW.plusSeconds(120)),NOW));reason("TOKEN_EXPIRED_OR_CLOCK_SKEW",()->ScpAuthentication.token(tokenData(NOW.minusSeconds(120),NOW.minusSeconds(1)),NOW));var node=tokenData(NOW,NOW.plusSeconds(120));((ObjectNode)node.path("access").path("token")).put("id","secret\r\nInjected:1");reason("INVALID_TOKEN",()->ScpAuthentication.token(node,NOW));}
    @Test void ec2MatchesIndependentPythonHmacVector(){var headers=ScpAuthentication.ec2(ScpProtocol.page(ScpProtocol.Kind.HOST,SCOPE,0,100),"SYNTHETIC_ACCESS","SYNTHETIC_ONLY_SECRET".toCharArray(),"test-region","test-api",NOW);assertEquals("20261012T080000Z",headers.get("X-Amz-Date"));assertTrue(headers.get("Authorization").endsWith("Signature=2f921fcf3160f40a55940d91937d5d8018d70db1ab2a688daf46b62ae476757b"));assertTrue(headers.get("Authorization").contains("SignedHeaders=path;x-amz-date"));}
    @Test void documentedEc2ProfileExcludesQueryButSignsPath(){var a=ScpAuthentication.ec2(ScpProtocol.page(ScpProtocol.Kind.HOST,SCOPE,0,100),"AK","SECRET".toCharArray(),"r","s",NOW);var b=ScpAuthentication.ec2(ScpProtocol.page(ScpProtocol.Kind.HOST,SCOPE,1,20),"AK","SECRET".toCharArray(),"r","s",NOW);assertEquals(a,b);assertNotEquals(a,ScpAuthentication.ec2(ScpProtocol.page(ScpProtocol.Kind.CLUSTER,SCOPE,0,100),"AK","SECRET".toCharArray(),"r","s",NOW));}
    @Test void invalidSigningScopeCannotSilentlyUseDocumentExample(){reason("INVALID_EC2_CONFIGURATION",()->ScpAuthentication.ec2(ScpProtocol.version(),"AK","SECRET".toCharArray(),null,"open-api",NOW));}
    @Test void requestResponseAndConfigurationStringRepresentationsHideSensitiveContent(){var request=ScpProtocol.authenticate("SECRET_USERNAME","a".repeat(512));assertFalse(request.toString().contains("SECRET"));var response=new ScpClient.Response(200,"application/json",bytes("SECRET_BODY"));assertFalse(response.toString().contains("SECRET"));assertFalse(settings(config()).toString().contains(TENANT));byte[] mutable=response.bytes();mutable[0]=0;assertEquals('S',response.bytes()[0]);}
    static class Time extends Clock {Instant now=NOW;public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId zone){return this;}public Instant instant(){return now;}}
    static class Exchange implements ScpClient.Exchange {
        final List<ScpProtocol.Request> calls=new ArrayList<>();final List<Map<String,String>> headers=new ArrayList<>();int readStatus=200;Time time;
        Exchange(Time time){this.time=time;}
        public ScpClient.Response execute(ScpProtocol.Request request,Map<String,String> headers){
            calls.add(request);this.headers.add(headers);Object data;
            if(request.path().contains("public-key"))data=Map.of("public_key",modulus);
            else if(request.path().equals("/janus/authenticate"))data=tokenData(time.now.minusSeconds(1),time.now.plusSeconds(120));
            else {if(readStatus!=200)return new ScpClient.Response(readStatus,"application/json",bytes("NEVER_ECHO_SOURCE_SECRET"));data=page(List.of(row()),"");}
            return new ScpClient.Response(200,"application/json",encoded(Map.of("message","","code",0,"data",data)));
        }
    }
    @Test void constructionDoesNotAuthenticateAndPasswordSessionIsReused(){var time=new Time();var exchange=new Exchange(time);var client=new ScpClient(settings(config()),secrets()::get,exchange,time);assertEquals(0,exchange.calls.size());client.page(ScpProtocol.Kind.HOST,0,100);client.page(ScpProtocol.Kind.HOST,0,100);assertEquals(4,exchange.calls.size());assertEquals("POST",exchange.calls.get(1).method());assertFalse(new String(exchange.calls.get(1).body(),StandardCharsets.UTF_8).contains("SYNTHETIC_PASSWORD_ONLY"));assertEquals("Token SYNTHETIC_TOKEN_ONLY",exchange.headers.get(2).get("Authorization"));}
    @Test void v2PublicKeyNeverReceivesCookieAuthorizationOrForwardedHeaders(){var c=config();c.put("legacy_cookie_required",true);var time=new Time();var exchange=new Exchange(time);new ScpClient(settings(c),secrets()::get,exchange,time).page(ScpProtocol.Kind.HOST,0,100);assertTrue(exchange.headers.get(0).isEmpty());assertTrue(exchange.headers.get(1).containsKey("Cookie"));assertFalse(exchange.headers.get(1).containsKey("Authorization"));}
    @Test void v1LegacyCookiePolicyIsExplicit(){var c=config();c.put("legacy_cookie_required",true);c.put("public_key_api","V1");var time=new Time();var exchange=new Exchange(time);new ScpClient(settings(c),secrets()::get,exchange,time).page(ScpProtocol.Kind.HOST,0,100);assertEquals("/janus/public-key",exchange.calls.get(0).path());assertTrue(exchange.headers.get(0).get("Cookie").startsWith("aCMPAuthToken="));}
    @Test void expiredSessionIsRenewedOnceUsingReportedExpiry(){var time=new Time();var exchange=new Exchange(time);var client=new ScpClient(settings(config()),secrets()::get,exchange,time);client.page(ScpProtocol.Kind.HOST,0,100);time.now=NOW.plusSeconds(91);client.page(ScpProtocol.Kind.HOST,0,100);assertEquals(6,exchange.calls.size());}
    @Test void authDenialDoesNotReplayLoginAndNextCallBacksOff(){var time=new Time();var exchange=new Exchange(time);var client=new ScpClient(settings(config()),secrets()::get,exchange,time);exchange.readStatus=401;reason("AUTHENTICATION_REJECTED",()->client.page(ScpProtocol.Kind.HOST,0,100));assertEquals(3,exchange.calls.size());reason("AUTHENTICATION_BACKOFF",()->client.page(ScpProtocol.Kind.HOST,0,100));assertEquals(3,exchange.calls.size());time.now=NOW.plusSeconds(61);exchange.readStatus=200;client.page(ScpProtocol.Kind.HOST,0,100);assertEquals(6,exchange.calls.size());}
    @Test void forbiddenAndRateLimitedReadsDoNotBecomeEmptyPages(){for(int status:List.of(403,429)){var time=new Time();var exchange=new Exchange(time);exchange.readStatus=status;var client=new ScpClient(settings(config()),secrets()::get,exchange,time);reason(status==403?"ACCESS_DENIED":"RATE_LIMITED",()->client.page(ScpProtocol.Kind.HOST,0,100));assertEquals(3,exchange.calls.size());reason("AUTHENTICATION_BACKOFF",()->client.page(ScpProtocol.Kind.HOST,0,100));}}
    @Test void ec2NeverCallsPasswordAuthentication(){var c=config();c.put("auth_mode","EC2");var time=new Time();var exchange=new Exchange(time);new ScpClient(settings(c),secrets()::get,exchange,time).page(ScpProtocol.Kind.HOST,0,100);assertEquals(1,exchange.calls.size());assertEquals("GET",exchange.calls.get(0).method());assertTrue(exchange.headers.get(0).get("Authorization").startsWith("AWS4-HMAC-SHA256 "));}
    @Test void malformedPageRequestHasNoNetworkSideEffects(){var time=new Time();var exchange=new Exchange(time);var client=new ScpClient(settings(config()),secrets()::get,exchange,time);reason("INVALID_PAGE_REQUEST",()->client.page(ScpProtocol.Kind.HOST,-1,100));assertTrue(exchange.calls.isEmpty());}
    @Test void transportFailuresAreRedactedAndLoginIsThrottled(){var time=new Time();var client=new ScpClient(settings(config()),secrets()::get,(request,headers)->{throw new IllegalStateException("PRIVATE_SECRET");},time);var failure=assertThrows(ScpProtocol.Failure.class,()->client.page(ScpProtocol.Kind.HOST,0,100));assertFalse(failure.toString().contains("PRIVATE_SECRET"));reason("AUTHENTICATION_BACKOFF",()->client.page(ScpProtocol.Kind.HOST,0,100));}
    @Test void offlinePreparationNeverClaimsConnectivityEvenWhenConfigurationIsComplete(){var report=ScpPreparationCheck.check(encoded(config()),secrets()::get);assertEquals("CONFIGURED_NOT_VERIFIED",report.get("configuration_status"));assertEquals(false,report.get("integration_ready"));assertEquals(0,report.get("http_requests_sent"));var c=config();c.put("enabled",false);assertEquals("CONFIG_PENDING",ScpPreparationCheck.check(encoded(c),k->null).get("configuration_status"));assertFalse(report.toString().contains("SYNTHETIC_PASSWORD_ONLY"));}
}
